package ro.leo.keypad;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
/** Explicit personal dictionary editor, stored only inside the IME package. */
public final class DictionaryActivity extends Activity {
 private final PersonalWords words=new PersonalWords();private EditText edit;private boolean adding;
 protected void onCreate(Bundle b){super.onCreate(b);words.load(getSharedPreferences("personal-words",0).getString("words",""));show();}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.WHITE);v.setPadding(8,8,8,8);return v;}
 private LinearLayout page(String title){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff171126);root.addView(text(title,21));setContentView(root);return root;}
 private void save(){getSharedPreferences("personal-words",0).edit().putString("words",words.save()).apply();}
 private void show(){adding=false;LinearLayout root=page("Dicționar personal · "+words.words().size()+"/256");final ArrayList<String> rows=new ArrayList<String>();rows.add("Adaugă un cuvânt");rows.addAll(words.words());ListView list=new ListView(this);list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));root.addView(text("OK adaugă / opțiuni · Înapoi",12));list.setOnItemClickListener(new android.widget.AdapterView.OnItemClickListener(){public void onItemClick(android.widget.AdapterView<?> parent,View view,final int i,long id){if(i==0)add();else new AlertDialog.Builder(DictionaryActivity.this).setTitle(rows.get(i)).setItems(new String[]{"Păstrează","Șterge cuvântul"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int n){if(n==1){words.remove(rows.get(i));save();show();}}}).show();}});list.requestFocus();root.post(new Runnable(){public void run(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(getWindow().getDecorView().getWindowToken(),0);}});}
 private void add(){adding=true;LinearLayout root=page("Cuvânt nou");root.addView(text("2–32 litere, inclusiv diacritice. Rămâne doar pe telefon.",15));edit=new EditText(this);edit.setTextColor(Color.WHITE);edit.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);root.addView(edit);root.addView(text("Soft stânga: salvează\nÎnapoi: anulează",13));edit.requestFocus();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);}
 public boolean onKeyDown(int key,KeyEvent e){if(adding&&key==KeyEvent.KEYCODE_MENU){if(e.getRepeatCount()==0){if(words.add(edit.getText().toString())){save();show();}else Toast.makeText(this,"Cuvânt invalid sau dicționar plin",1).show();}return true;}return super.onKeyDown(key,e);}
 public void onBackPressed(){if(adding)show();else super.onBackPressed();}
}
